Let $\lambda \in (0, 1)$, then 

\begin{equation*}
(\lambda x_1 + (1- \lambda) x_2)(S) = \lambda x_1(S) + (1- \lambda)x_2(S).
\end{equation*}

Therefore, 
\begin{equation*}
\begin{split}
e_v(S, \lambda x_1 + (1- \lambda) x_2) = v(S)-(\lambda x_1 + (1- \lambda) x_2)(S) \\
= \lambda v(S) + (1- \lambda) v(S) - (\lambda x_1(S) + (1- \lambda)x_2(S)) \\
= \lambda e_v(S, x_1) + (1- \lambda)e_v(S, x_2).
\end{split}
\end{equation*}

Since $u_S$ is strictly monotone increasing we have that
\begin{equation*}
u_S\circ e_v(S, x_1) < u_S\circ e_v(S, \lambda x_1 + (1-\lambda) x_2) < u_S\circ e_v(S, x_2).
\end{equation*}

Indirectly assume that $\exists x^{1}\in X(\mathcal{E}_v^{\mathbf{u}}, t_1) \setminus X(\mathcal{A}^\ast, t_1)$. This means that $\exists S \in \mathcal{A}^*$ such that

\begin{equation} u_S \circ e_v(S, x^1) > t_1.
\end{equation}

By Lemma \ref{lemma:rest1} we have that for each $S\in \mathcal{S}_{x^1}$ $\exists \mathcal{B}^\ast_S\subseteq \mathcal{E}_v^{\mathbf{u}}$, $\mathcal{B}^\ast_S\in \mathcal{D}_{S^1}^{\mathcal{A}^\ast}$ such that 

\begin{equation} u_{S}\circ e_v(S, x^\ast) \leq \sum_{T\in \mathcal{B}^*_S}u_T\circ e_v(T, x^\ast).
\end{equation}

Since $t_1 \leq 0$ and for all $x\in X(\mathcal{E}_v^{\mathbf{u}}, t_1)$ and $T\in \mathcal{E}_v^{\mathbf{u}}$ it holds that $u_T\circ e_v(T, x) \leq t_1$, therefore for all $S\in \mathcal{S}_{x^1}$

\begin{equation} u_{S}\circ e_v(S, x^\ast) \leq \sum_{T\in \mathcal{B}^\ast_S}u_T\circ e_v(T, x^\ast) \leq t_1 \ .
\end{equation}

By \eqref{eq:e>t}, \eqref{eq:e<=t} and the continuity of $u_S$, for every $S\in \mathcal{S}_{x^1}$ there exists $\lambda_S \in [0,1]$ such that

\begin{equation*}
u_S\circ e_v(S, \lambda_S x^\ast + (1-\lambda_S) x^1) = t_1 \ .
\end{equation*}

